raw_response:
VAR
    Overload_Timer : TON;
END_VAR

// Calculate 300% of rated current (41.5 A * 3.0 = 124.5 A)
// Latch Overload_Alarm and stop the motor if current exceeds this for 3 seconds while running

Overload_Timer(IN := Motor_Running AND (Motor_Current > 124.5),
               PT := T#3S);

IF Overload_Timer.Q THEN
    Overload_Alarm := TRUE;
END_IF;

IF Fault_Reset THEN
    Overload_Alarm := FALSE;
END_IF;

IF Overload_Alarm THEN
    Motor_Stop := TRUE;
END_IF;

